package banghak.home.halley.adapter.outbound.persistence;
import banghak.home.halley.domain.budget.*; import static banghak.home.halley.adapter.outbound.persistence.support.JooqMapping.toInstant; import org.jooq.DSLContext; import org.jooq.Record; import org.springframework.stereotype.Repository; import java.util.Optional; import static banghak.home.halley.adapter.outbound.persistence.jdbc.HouseholdBudgetFinancingTable.*; import static banghak.home.halley.adapter.outbound.persistence.support.JooqMapping.toEnum;
@Repository public class HouseholdBudgetFinancingRepository { private final DSLContext dsl; public HouseholdBudgetFinancingRepository(DSLContext dsl){this.dsl=dsl;} public BudgetFinancing save(BudgetFinancing f){Long id=dsl.insertInto(TABLE).set(PLAN_ID,f.planId()).set(LOAN_AMOUNT,f.loanAmount()).set(LOAN_RATIO,f.loanRatio()).set(INTEREST_RATE,f.interestRate()).set(TERM_MONTHS,f.termMonths()).set(REPAYMENT_TYPE,f.repaymentType().name()).set(MONTHLY_PAYMENT,f.monthlyPayment()).set(IS_ESTIMATE,f.estimate()).returningResult(ID).fetchOne().component1(); return findById(id).orElseThrow();} public Optional<BudgetFinancing> findById(Long id){return dsl.selectFrom(TABLE).where(ID.eq(id)).fetchOptional().map(this::map);} public Optional<BudgetFinancing> findByPlanId(Long id){return dsl.selectFrom(TABLE).where(PLAN_ID.eq(id)).fetchOptional().map(this::map);} public void delete(Long id){dsl.deleteFrom(TABLE).where(ID.eq(id)).execute();} private BudgetFinancing map(Record r){return new BudgetFinancing(r.get(ID),r.get(PLAN_ID),r.get(LOAN_AMOUNT),r.get(LOAN_RATIO),r.get(INTEREST_RATE),r.get(TERM_MONTHS),toEnum(RepaymentType.class,r.get(REPAYMENT_TYPE)),r.get(MONTHLY_PAYMENT),r.get(IS_ESTIMATE),toInstant(r.get(CREATED_AT)),toInstant(r.get(UPDATED_AT)));} }
